// Expected outcomes are literal fixtures, not generated by the matcher.
func TestRegexFilterExpected(t *testing.T) {
	cases := []struct {
		name, must, exclude, input, reason string
		allowed                            bool
	}{
		{"empty", "", "", "Title", "allowed", true},
		{"include", "1080p|720p", "", "Title 1080p", "allowed", true},
		{"missing", "1080p", "", "Title 720p", "must_contain_not_matched", false},
		{"exclude", "", "sample", "sample", "not_in_matched", false},
		{"both", "sample", "sample", "sample", "not_in_matched", false},
		{"case sensitive", "TITLE", "", "Title", "must_contain_not_matched", false},
		{"inline case", "(?i)TITLE", "", "Title", "allowed", true},
		{"search", "Title", "", "[Group] Title 01", "allowed", true},
		{"anchored", "^Title$", "", "Title 01", "must_contain_not_matched", false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			f, err := CompileRegexFilter(RegexFilter{MustContain: c.must, NotIn: c.exclude})
			if err != nil {
				t.Fatal(err)
			}
			d := f.MatchReleaseTitle(c.input)
			if d.Allowed != c.allowed || d.Reason != c.reason {
				t.Fatalf("got %+v, want allowed=%v reason=%s", d, c.allowed, c.reason)
			}
		})
	}
}

func TestRegexFilterRejectsInvalid(t *testing.T) {
	for _, pattern := range []string{"[", "(?=x)", `(x)\1`, strings.Repeat("a", 4097), string([]byte{0xff})} {
		for _, p := range []RegexFilter{{MustContain: pattern}, {NotIn: pattern}} {
			if _, err := CompileRegexFilter(p); err == nil {
				t.Errorf("accepted invalid pattern %q", pattern)
			}
		}
	}
	f, _ := CompileRegexFilter(RegexFilter{})
	for _, input := range []string{strings.Repeat("x", 8193), string([]byte{0xff})} {
		if d := f.MatchReleaseTitle(input); d.Allowed || d.Reason != "filter_input_invalid" {
			t.Fatalf("invalid title allowed: %+v", d)
		}
	}
	var zero CompiledRegexFilter
	if d := zero.MatchReleaseTitle("Title"); d.Allowed {
		t.Fatal("zero compiled filter allowed input")
	}
}

// File rules match the filename of a first-level video, never the directory
// or the torrent name.
func TestRegexFilterMatchesFilenameOnly(t *testing.T) {
	f, _ := CompileRegexFilter(RegexFilter{MustContain: `^\[Grp\].*\.mkv$`, NotIn: `sample`})
	cases := []struct {
		input, normalized, reason string
		allowed                   bool
	}{
		{"Show/[Grp] 01.mkv", "[Grp] 01.mkv", "allowed", true},
		{`Show\[Grp] 01.mkv`, "[Grp] 01.mkv", "allowed", true},
		{"[Grp] 01.mkv", "[Grp] 01.mkv", "allowed", true},
		// A directory or torrent name cannot satisfy must_contain or trip not_in.
		{"[Grp] Show/01.mkv", "01.mkv", "must_contain_not_matched", false},
		{"sample Show/[Grp] 01.mkv", "[Grp] 01.mkv", "allowed", true},
		{"Show/[Grp] sample.mkv", "[Grp] sample.mkv", "not_in_matched", false},
	}
	for _, c := range cases {
		d := f.MatchFilename(c.input)
		if d.Allowed != c.allowed || d.Input != c.normalized || d.Reason != c.reason {
			t.Errorf("%q: %+v", c.input, d)
		}
	}
	for _, input := range []string{"", "/a.mkv", `C:\a.mkv`, `C:a.mkv`, `\\host\a.mkv`, "../a.mkv", "a/../b.mkv", `a\..\b.mkv`, "a/./b.mkv", "a//b.mkv", "a/b/", "a\x00b", "a\nb", string([]byte{0xff}), strings.Repeat("a", 4097)} {
		if d := f.MatchFilename(input); d.Allowed || d.Reason != "filter_path_invalid" {
			t.Errorf("unsafe path %q: %+v", input, d)
		}
	}
}

func TestFileRulesAllowRegexEscapes(t *testing.T) {
	for _, pattern := range []string{`\.mkv$`, `\d{2}`, `(?i)\bNCOP\b`} {
		encoded, _ := json.Marshal(pattern)
		raw := `{"must_contain":` + string(encoded) + `,"not_in":` + string(encoded) + `}`
		if err := ValidateFileRulesJSON(json.RawMessage(raw)); err != nil {
			t.Errorf("file rule %q must stay valid: %v", pattern, err)
		}
	}
}

func TestFileRulesRejectPathSeparators(t *testing.T) {
	for _, pattern := range []string{"extras/", "a/b", `Season\d+/`} {
		for _, field := range []string{"must_contain", "not_in"} {
			raw := `{"must_contain":"","not_in":""}`
			encoded, _ := json.Marshal(pattern)
			raw = strings.Replace(raw, `"`+field+`":""`, `"`+field+`":`+string(encoded), 1)
			err := ValidateFileRulesJSON(json.RawMessage(raw))
			var typed *FileRuleError
			if !errors.As(err, &typed) || typed.Code != ErrCodeFileRulePathSeparator || typed.Field != field {
				t.Errorf("%s %q: err=%v, want the typed separator error", field, pattern, err)
			}
		}
	}
	if err := ValidateFileRulesJSON(json.RawMessage(`{"must_contain":"(?i)^\\[Grp\\]","not_in":"NCOP|PV"}`)); err != nil {
		t.Fatalf("a backslash regex escape must be accepted (no Windows path compatibility): %v", err)
	}
	if err := ValidateFileRulesJSON(json.RawMessage(`{"must_contain":"(?i)ncop|[.]mkv$","not_in":""}`)); err != nil {
		t.Fatalf("a rule without separators must be accepted: %v", err)
	}
}

func TestDefaultFileRulesAreEmpty(t *testing.T) {
	value, err := DefaultSectionValue(SectionFileRules)
	if err != nil {
		t.Fatal(err)
	}
	if rules, ok := value.(FileFilterRules); !ok || rules != (FileFilterRules{}) {
		t.Fatalf("default file rules = %#v, want empty", value)
	}
}

func TestRegexFilterInventory(t *testing.T) {
	kinds := filekinds.Version
	f, _ := CompileRegexFilter(RegexFilter{NotIn: `NCOP`})
	paths := []string{
		"Show/01.mkv",      // first-level video: selected
		"Show/NCOP.mkv",    // first-level video: not_in on its filename
		"Show/01.chs.ass",  // first-level subtitle: not subject to rules
		"Show/cover.jpg",   // other kind
		"Show/SPs/02.mkv",  // nested video
		"Show/Fonts/a.ass", // nested subtitle
	}
	d, err := f.SelectOrganizationFiles(kinds, paths)
	if err != nil || !d.DownloadAllowed || len(d.Decisions) != len(paths) {
		t.Fatalf("selection: %+v %v", d, err)
	}
	if got := d.SelectedOrdinals; len(got) != 2 || got[0] != 0 || got[1] != 2 {
		t.Fatalf("selected ordinals = %v, want [0 2]", got)
	}
	for index, want := range []string{"allowed", "not_in_matched", "allowed", "ignored_kind", "ignored_nested", "ignored_nested"} {
		if d.Decisions[index].Reason != want {
			t.Errorf("decision %d (%s) = %q, want %q", index, paths[index], d.Decisions[index].Reason, want)
		}
	}
	// A not_in that matches only the torrent name never excludes the torrent.
	byName, _ := CompileRegexFilter(RegexFilter{NotIn: `Show`})
	if d, err = byName.SelectOrganizationFiles(kinds, []string{"Show/01.mkv"}); err != nil || d.DownloadAllowed != true {
		t.Fatalf("torrent name must not be matched: %+v %v", d, err)
	}
	// A single-file torrent is its own first level.
	if d, err = f.SelectOrganizationFiles(kinds, []string{"Movie.mkv"}); err != nil || !d.DownloadAllowed {
		t.Fatalf("single-file torrent: %+v %v", d, err)
	}
	// Without a selected video there is nothing to download.
	if d, err = f.SelectOrganizationFiles(kinds, []string{"Show/01.chs.ass", "Show/SPs/02.mkv"}); err != nil || d.DownloadAllowed || d.Reason != "no_applicable_files" {
		t.Fatalf("no selected video: %+v %v", d, err)
	}
	// A frozen version this build does not know classifies nothing as a video.
	if d, err = f.SelectOrganizationFiles("file-kinds-v999", []string{"Show/01.mkv"}); err != nil || d.DownloadAllowed {
		t.Fatalf("unknown frozen kinds version: %+v %v", d, err)
	}
	for _, p := range [][]string{{"a/b.mkv", `a\b.mkv`}, {"ok.mkv", "../unsafe"}} {
		if _, err := f.SelectOrganizationFiles(kinds, p); err == nil {
			t.Fatalf("invalid inventory accepted: %q", p)
		}
	}
}
